var start = result.indexOf('id="cp_img"');
var html = '';
if (start !== -1) {
    var end = result.indexOf('</div>', start);
    html = result.substring(start, end);
}
var urls = [];
var re = /data-src="([^"]+)"/g;
var m;
while ((m = re.exec(html)) != null) {
    urls.push(m[1]);
}
var out = '';
for (var i = 0; i < urls.length; i++) {
    out += '<img src="' + urls[i] + '">\n';
}
out;

