                "if-modified-since": String(new Date()).replace(/(.*?)\s(.*?)\s(.*?)\s(.*?)GMT.*/,'$1, $3 $2 $4 GMT')
            }
        };
        result = baseUrl+'post.json?key=' + key + '&sortType=0&offset=' + offset + '&limit=20,' + JSON.stringify(header);
}

